      "stepByStep": "Statement (A) is TRUE (Lippes loop induces sterile leukocytosis and phagocytosis). Statement (B) is FALSE (Saheli is NON-steroidal and taken ONCE weekly). Statement (C) is TRUE (LNG-20 and Progestasert thin the endometrium and thicken cervical mucus). Statement (D) is FALSE (diaphragms/vaults are REUSABLE rubber barriers). Statement (E) is TRUE (Multiload 375 releases copper suppressing motility). Thus, A, C, and E are correct.",
      "finalAnswer": "Option C: Statements (A), (C), and (E) only",
