    "question": "Evaluate the following four statements (A-D) concerning Sexually Transmitted Infections (STIs):\n(A) Hepatitis B, Genital herpes, and HIV infections are not completely curable.\n(B) Chlamydiasis, Gonorrhoea, and Syphilis are viral STIs that cannot be treated with antibiotics.\n(C) Untreated STIs in women can lead to pelvic inflammatory diseases, ectopic pregnancies, and infertility.\n(D) STIs cannot be transmitted to the newborn during vaginal delivery.\nWhich of the above statements are CORRECT?",
