    "question": "A 32-year-old man presents with primary infertility of 3 years duration. Semen analysis shows a normal ejaculate volume of 3.2 mL, but the total sperm count is only 2 million/mL (normal >15 million/mL) with only 12% progressive motility (oligoasthenozoospermia). Physical examination confirms normal testicular size and secondary sexual traits. Which ART procedure offers the highest probability of fertilization and pregnancy using his own biological spermatozoa?",
