    "questionNumber": 468,
    "question": "A 24-year-old female presents to the gynecology clinic with recurrent lower abdominal pain, purulent cervical discharge, and dyspareunia. Laparoscopy reveals extensive pelvic adhesions and bilateral hydrosalpinx with completely occluded fallopian tubes. Microbiological swab confirms past untreated Chlamydia trachomatis infection. The couple desires biological children. What is the most appropriate assisted reproductive strategy for this patient?",
    "options": {
      "A": "Gamete Intra-Fallopian Transfer (GIFT), because the ovaries are still functional",
      "B": "In Vitro Fertilization followed by Intra-Uterine Transfer (IVF-IUT), as it bypasses the irreversibly damaged fallopian tubes entirely",
      "C": "Artificial Insemination into the cervix (IUI), to push sperms past the tubal block",
      "D": "Administration of high-dose oral contraceptive pills for 6 months to dissolve tubal scars"
    },
    "optionsList": [
      "Gamete Intra-Fallopian Transfer (GIFT), because the ovaries are still functional",
      "In Vitro Fertilization followed by Intra-Uterine Transfer (IVF-IUT), as it bypasses the irreversibly damaged fallopian tubes entirely",
      "Artificial Insemination into the cervix (IUI), to push sperms past the tubal block",
      "Administration of high-dose oral contraceptive pills for 6 months to dissolve tubal scars"
    ],
    "correctAnswer": "B",
    "correctOption": "B",
    "correctIndex": 1,
    "explanation": "1. CONCEPT:\nManagement of bilateral tubal occlusion secondary to PID.\n\n2. STEP-BY-STEP SOLUTION:\nPelvic inflammatory disease (PID) from untreated Chlamydia causes bilateral tubal scarring and occlusion. Since fallopian tubes are blocked, gamete encounter in vivo is impossible, ruling out GIFT and IUI. IVF fertilizes oocytes in vitro and deposits the developing embryo directly into the uterine cavity (IUT), completely circumventing the fallopian tubes.\n\n3. FINAL ANSWER:\nOption B: In Vitro Fertilization followed by Intra-Uterine Transfer (IVF-IUT), as it bypasses the irreversibly damaged fallopian tubes entirely\n\n4. WHY OTHER OPTIONS ARE WRONG:\nGIFT and IUI require patent fallopian tubes; oral pills cannot reverse fibrous tubal adhesions.",
    "solutionStructured": {
      "concept": "Management of bilateral tubal occlusion secondary to PID.",
      "stepByStep": "Pelvic inflammatory disease (PID) from untreated Chlamydia causes bilateral tubal scarring and occlusion. Since fallopian tubes are blocked, gamete encounter in vivo is impossible, ruling out GIFT and IUI. IVF fertilizes oocytes in vitro and deposits the developing embryo directly into the uterine cavity (IUT), completely circumventing the fallopian tubes.",
      "finalAnswer": "Option B: In Vitro Fertilization followed by Intra-Uterine Transfer (IVF-IUT), as it bypasses the irreversibly damaged fallopian tubes entirely",
      "whyOtherOptionsWrong": "GIFT and IUI require patent fallopian tubes; oral pills cannot reverse fibrous tubal adhesions."
    },
