    "id": "reproductive-health-mcq-469",
    "questionNumber": 469,
    "question": "A 32-year-old man presents with primary infertility of 3 years duration. Semen analysis shows a normal ejaculate volume of 3.2 mL, but the total sperm count is only 2 million/mL (normal >15 million/mL) with only 12% progressive motility (oligoasthenozoospermia). Physical examination confirms normal testicular size and secondary sexual traits. Which ART procedure offers the highest probability of fertilization and pregnancy using his own biological spermatozoa?",
    "options": {
      "A": "Standard IVF with petri-dish co-incubation",
      "B": "Vasectomy followed by immediate re-anastomosis",
      "C": "Intra-Cytoplasmic Sperm Injection (ICSI)",
      "D": "GIFT using husband's semen"
    },
    "optionsList": [
      "Standard IVF with petri-dish co-incubation",
      "Vasectomy followed by immediate re-anastomosis",
      "Intra-Cytoplasmic Sperm Injection (ICSI)",
      "GIFT using husband's semen"
    ],
    "correctAnswer": "C",
    "correctOption": "C",
    "correctIndex": 2,
    "explanation": "1. CONCEPT:\nAdvanced ART selection in severe oligoasthenozoospermia.\n\n2. STEP-BY-STEP SOLUTION:\nIn severe oligoasthenozoospermia, spermatozoa cannot swim to or penetrate the zona pellucida in vivo (ruling out GIFT) or even in standard IVF (which requires ~50,000 motile sperms per egg). ICSI directly bypasses both motility and penetration barriers by micro-injecting a single selected viable sperm into the ooplasm.\n\n3. FINAL ANSWER:\nOption C: Intra-Cytoplasmic Sperm Injection (ICSI)\n\n4. WHY OTHER OPTIONS ARE WRONG:\nStandard IVF fails due to low sperm count; vasectomy causes sterility.",
    "solutionStructured": {
      "concept": "Advanced ART selection in severe oligoasthenozoospermia.",
      "stepByStep": "In severe oligoasthenozoospermia, spermatozoa cannot swim to or penetrate the zona pellucida in vivo (ruling out GIFT) or even in standard IVF (which requires ~50,000 motile sperms per egg). ICSI directly bypasses both motility and penetration barriers by micro-injecting a single selected viable sperm into the ooplasm.",
      "finalAnswer": "Option C: Intra-Cytoplasmic Sperm Injection (ICSI)",
      "whyOtherOptionsWrong": "Standard IVF fails due to low sperm count; vasectomy causes sterility."
    },
