    "question": "A 22-year-old unmarried female reports to an emergency clinic 36 hours after an incident of non-consensual unprotected sexual intercourse (rape). She is extremely distressed and anxious about becoming pregnant. Which of the following medical interventions is the most effective and appropriate immediate step?",
